def calculate_n(a, b, c):
    S = a + b + c
    Q = a*b + b*c + c*a
    numerator = S * (Q + 1)
    denominator = 4 * a * b * c

    # Check if n is an integer
    if denominator == 0:
        return None

    if numerator % denominator == 0:
        return numerator // denominator
    else:
        return None

triples = []

# a=1
for a in range(1, 5):
    for b in range(a + 1, 7):
        for c in range(b + 1, 16):
            if a + b + c <= 15:
                triples.append((a, b, c))

print(f"Total triples found: {len(triples)}")

n_values = set()
integer_n_values = []

for a, b, c in triples:
    n = calculate_n(a, b, c)
    if n is not None:
        n_values.add(n)
        integer_n_values.append((a, b, c, n))

print("\nInteger n values observed:")
for item in integer_n_values:
    print(item)

print("\nSet of observed integer n values:", sorted(list(n_values)))

# Check for small solutions to 11*k^2 - 17*d^2 = 1
# Search d from 1 to 10
for d in range(1, 11):
    target = 1 + 17 * d**2
    if target % 11 == 0:
        k_squared = target // 11
        k = int(k_squared**0.5)
        if k*k == k_squared:
            print(f"Found solution (k, d) = ({k}, {d}) for 11k^2 - 17d^2 = 1")
            break
else:
    print("No small solution found for 11k^2 - 17d^2 = 1 in the tested range.")
